      "id": "r2",
      "type": "verse",
      "lines": [
        {
          "n": 1,
          "text": "तस्मादनन्तमजरं परमं विकासि",
          "end": "line"
        },
        {
          "n": 2,
          "text": "तद्ब्रह्म चिन्तय किमेभिरसद्विकल्पैः ।",
          "end": "line"
        },
        {
          "n": 3,
          "text": "यस्यानुषङ्गिण इमे भुवनाधिपत्य-",
          "end": "hyphen"
        },
        {
          "n": 4,
          "text": "भोगादयः कृपणलोकमता भवन्ति ॥ ७६ ॥",
          "end": "space"
        }
      ],
      "uncertain": false,
      "note": null
    },
    {
      "id": "r3",
      "type": "verse",
      "lines": [
        {
          "n": 1,
          "text": "पातालमाविशसि यासि नभो विलङ्घ्य",
          "end": "line"
        },
        {
          "n": 2,
          "text": "दिङ्मण्डलं भ्रमसि मानसचापलेन ।",
          "end": "line"
        },
        {
          "n": 3,
          "text": "भ्रान्त्यापि जातु विमलं कथमात्मनीनं",
          "end": "line"
        },
        {
          "n": 4,
          "text": "तद्ब्रह्म न स्मरसि निर्वृतिमेषि येन ॥ ७७ ॥",
          "end": "space"
        }
      ],
      "uncertain": false,
      "note": null
    },
    {
      "id": "r4",
      "type": "verse",
      "lines": [
        {
          "n": 1,
          "text": "रात्रिः सैव पुनः स एव दिवसो मत्वाबुधा जन्तवो",
          "end": "line"
        },
        {
          "n": 2,
          "text": "धावन्त्युद्यमिनस्तथैव निभृतप्रारब्धतत्तत्क्रियाः ।",
          "end": "line"
        },
        {
          "n": 3,
          "text": "व्यापारैः पुनरुक्तभुक्तविषयैरेवंविधेनामुना",
          "end": "line"
        },
        {
          "n": 4,
          "text": "संसारेण कदर्थिताः कथमहो मोहान्न लज्जामहे ॥ ७८ ॥",
          "end": "space"
        }
      ],
      "uncertain": false,
      "note": null
    },
    {
      "id": "r5",
      "type": "verse",
      "lines": [
        {
          "n": 1,
          "text": "मही रम्या शय्या विपुलमुपधानं भुजलता",
          "end": "line"
        },
        {
          "n": 2,
          "text": "वितानं चाकाशं व्यजनमनुकूलोयमनिलः ।",
          "end": "line"
        }
      ],
      "uncertain": false,
      "note": null
    },
